/**
 * Writes <sourceDir>/.playwright/cli.config.json with stealth defaults so
 * `playwright-cli open` auto-loads them from the agent's cwd. Skipped when a
 * config already exists so user-provided files are never clobbered.
 *
 * NOTE: Playwright's MCP browser config treats `initScript` entries as file
 * paths, not inline source. The stealth script is written alongside the config
 * and referenced by absolute path. Inline strings silently fail the daemon.
 */

import fs from 'node:fs/promises';
import path from 'node:path';

async function pathExists(p: string): Promise<boolean> {
  try {
    await fs.access(p);
    return true;
  } catch {
    return false;
  }
}

const STEALTH_INIT_SCRIPT = `delete Object.getPrototypeOf(navigator).webdriver;

Object.defineProperty(navigator, 'plugins', {
  get: () => {
    const arr = [
      { name: 'Chrome PDF Plugin', filename: 'internal-pdf-viewer', description: 'Portable Document Format' },
      { name: 'Chrome PDF Viewer', filename: 'mhjfbmdgcfjbbpaeojofohoefgiehjai', description: '' },
      { name: 'Native Client', filename: 'internal-nacl-plugin', description: '' },
    ];
    arr.__proto__ = PluginArray.prototype;
    return arr;
  },
});

window.chrome = window.chrome || {};
window.chrome.runtime = window.chrome.runtime || {
  PlatformOs: { MAC: 'mac', WIN: 'win', ANDROID: 'android', CROS: 'cros', LINUX: 'linux', OPENBSD: 'openbsd' },
  PlatformArch: { ARM: 'arm', X86_32: 'x86-32', X86_64: 'x86-64' },
  PlatformNaclArch: { ARM: 'arm', X86_32: 'x86-32', X86_64: 'x86-64' },
  RequestUpdateCheckStatus: { THROTTLED: 'throttled', NO_UPDATE: 'no_update', UPDATE_AVAILABLE: 'update_available' },
  OnInstalledReason: { INSTALL: 'install', UPDATE: 'update', CHROME_UPDATE: 'chrome_update', SHARED_MODULE_UPDATE: 'shared_module_update' },
  OnRestartRequiredReason: { APP_UPDATE: 'app_update', OS_UPDATE: 'os_update', PERIODIC: 'periodic' },
};
`;

function buildStealthConfig(initScriptPath: string) {
  return {
    browser: {
      browserName: 'chromium',
      launchOptions: {
        headless: true,
        args: ['--disable-blink-features=AutomationControlled'],
        ignoreDefaultArgs: ['--enable-automation'],
      },
      contextOptions: {
        viewport: { width: 1920, height: 1080 },
        locale: 'en-US',
        extraHTTPHeaders: { 'Accept-Language': 'en-US,en;q=0.9' },
        userAgent:
          'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
      },
      initScript: [initScriptPath],
    },
  };
}

export type StealthConfigWriteResult = 'wrote' | 'skipped-existing';

export async function writePlaywrightStealthConfig(
  sourceDir: string,
): Promise<{ result: StealthConfigWriteResult; configPath: string }> {
  const playwrightDir = path.join(sourceDir, '.playwright');
  const configPath = path.join(playwrightDir, 'cli.config.json');
  if (await pathExists(configPath)) {
    return { result: 'skipped-existing', configPath };
  }
  const initScriptPath = path.join(playwrightDir, 'scripts', 'stealth.js');
  await fs.mkdir(path.dirname(initScriptPath), { recursive: true });
  await fs.writeFile(initScriptPath, STEALTH_INIT_SCRIPT);
  await fs.writeFile(configPath, JSON.stringify(buildStealthConfig(initScriptPath), null, 2));
  return { result: 'wrote', configPath };
}

/**
 * Parsing for the single model setting, `SHANNON_AI_MODEL=<provider>:<model-id>`.
 *
 * Mirrors apps/worker/src/ai/models.ts. The CLI cannot import from the worker
 * package (it ships as a standalone bundle), so the provider list and the parse
 * rule are duplicated here deliberately and must stay in sync.
 */

/**
 * Providers Shannon curates with their own credential variables, config sections,
 * and setup flows. Any other pi provider is reachable via the generic credential
 * path. Mirrors CURATED_PROVIDERS in apps/worker/src/ai/models.ts.
 */
export const CURATED_PROVIDERS = ['anthropic', 'openai', 'xai', 'amazon-bedrock'] as const;

export type CuratedProviderId = (typeof CURATED_PROVIDERS)[number];

export function isCuratedProvider(value: string): value is CuratedProviderId {
  return (CURATED_PROVIDERS as readonly string[]).includes(value);
}

/** Generic API key, honored for any provider Shannon does not curate. Mirrors the worker. */
export const GENERIC_API_KEY_ENV = 'SHANNON_AI_API_KEY';

/**
 * Env vars carrying each curated provider's API key, in precedence order. Any one of
 * them satisfies the provider. Mirrors PROVIDER_API_KEY_ENV in apps/worker/src/ai/models.ts.
 */
export const PROVIDER_API_KEY_ENV: Readonly<Record<CuratedProviderId, readonly string[]>> = {
  anthropic: ['ANTHROPIC_API_KEY', 'CLAUDE_CODE_OAUTH_TOKEN'],
  openai: ['OPENAI_API_KEY'],
  xai: ['XAI_API_KEY'],
  'amazon-bedrock': ['AWS_BEARER_TOKEN_BEDROCK'],
};

/** Additional env vars a curated provider requires beyond its API key. All must be set. */
export const PROVIDER_EXTRA_ENV: Readonly<Record<CuratedProviderId, readonly string[]>> = {
  anthropic: [],
  openai: [],
  xai: [],
  'amazon-bedrock': ['AWS_REGION'],
};

/** Human-readable credential requirement, used in "nothing configured" errors. */
export const PROVIDER_CREDENTIAL_HINT: Readonly<Record<CuratedProviderId, string>> = {
  anthropic: 'ANTHROPIC_API_KEY (or CLAUDE_CODE_OAUTH_TOKEN)',
  openai: 'OPENAI_API_KEY',
  xai: 'XAI_API_KEY',
  'amazon-bedrock': 'AWS_REGION and AWS_BEARER_TOKEN_BEDROCK',
};

/** Model used when SHANNON_AI_MODEL is unset. */
export const DEFAULT_MODEL_SPEC = 'anthropic:claude-sonnet-4-6';

export interface ModelSpec {
  providerId: string;
  modelId: string;
}

/**
 * Parse a `<provider>:<model-id>` spec. Splits on the first colon only, so colons
 * inside a model ID survive (`amazon-bedrock:us.anthropic.claude-opus-4-5-20251101-v1:0`).
 * The provider id is passed through as given — the worker's preflight validates it
 * against pi. Returns an error string rather than throwing, for the CLI's flow.
 */
export function parseModelSpec(spec: string): ModelSpec | string {
  const trimmed = spec.trim();
  const separator = trimmed.indexOf(':');
  const malformed = `SHANNON_AI_MODEL must be "<provider>:<model-id>", got "${trimmed}". Example: ${DEFAULT_MODEL_SPEC}`;
  if (separator === -1) return malformed;

  const providerId = trimmed.slice(0, separator).trim();
  const modelId = trimmed.slice(separator + 1).trim();
  if (!providerId || !modelId) return malformed;

  return { providerId, modelId };
}

/** Resolve the run's model spec from the environment, or an error string. */
export function resolveModelSpec(): ModelSpec | string {
  return parseModelSpec(process.env.SHANNON_AI_MODEL || DEFAULT_MODEL_SPEC);
}

package leetcode

import (
	"fmt"
	"testing"
)

type question1 struct {
	para1
	ans1
}

// para 是参数
// one 代表第一个参数
type para1 struct {
	nums   []int
	target int
}

// ans 是答案
// one 代表第一个答案
type ans1 struct {
	one []int
}

func Test_Problem1(t *testing.T) {

	qs := []question1{
		{
			para1{[]int{3, 2, 4}, 6},
			ans1{[]int{1, 2}},
		},

		{
			para1{[]int{3, 2, 4}, 5},
			ans1{[]int{0, 1}},
		},

		{
			para1{[]int{0, 8, 7, 3, 3, 4, 2}, 11},
			ans1{[]int{1, 3}},
		},

		{
			para1{[]int{0, 1}, 1},
			ans1{[]int{0, 1}},
		},

		{
			para1{[]int{0, 3}, 5},
			ans1{[]int{}},
		},
		// 如需多个测试，可以复制上方元素。
	}

	fmt.Printf("------------------------Leetcode Problem 1------------------------\n")

	for _, q := range qs {
		_, p := q.ans1, q.para1
		fmt.Printf("【input】:%v       【output】:%v\n", p, twoSum(p.nums, p.target))
	}
	fmt.Printf("\n\n\n")
}

package leetcode

import (
	"fmt"
	"testing"

	"github.com/halfrost/LeetCode-Go/structures"
)

type question2 struct {
	para2
	ans2
}

// para 是参数
// one 代表第一个参数
type para2 struct {
	one     []int
	another []int
}

// ans 是答案
// one 代表第一个答案
type ans2 struct {
	one []int
}

func Test_Problem2(t *testing.T) {

	qs := []question2{

		{
			para2{[]int{}, []int{}},
			ans2{[]int{}},
		},

		{
			para2{[]int{1}, []int{1}},
			ans2{[]int{2}},
		},

		{
			para2{[]int{1, 2, 3, 4}, []int{1, 2, 3, 4}},
			ans2{[]int{2, 4, 6, 8}},
		},

		{
			para2{[]int{1, 2, 3, 4, 5}, []int{1, 2, 3, 4, 5}},
			ans2{[]int{2, 4, 6, 8, 0, 1}},
		},

		{
			para2{[]int{1}, []int{9, 9, 9, 9, 9}},
			ans2{[]int{0, 0, 0, 0, 0, 1}},
		},

		{
			para2{[]int{9, 9, 9, 9, 9}, []int{1}},
			ans2{[]int{0, 0, 0, 0, 0, 1}},
		},

		{
			para2{[]int{2, 4, 3}, []int{5, 6, 4}},
			ans2{[]int{7, 0, 8}},
		},

		{
			para2{[]int{1, 8, 3}, []int{7, 1}},
			ans2{[]int{8, 9, 3}},
		},
		// 如需多个测试，可以复制上方元素。
	}

	fmt.Printf("------------------------Leetcode Problem 2------------------------\n")

	for _, q := range qs {
		_, p := q.ans2, q.para2
		fmt.Printf("【input】:%v       【output】:%v\n", p, structures.List2Ints(addTwoNumbers(structures.Ints2List(p.one), structures.Ints2List(p.another))))
	}
	fmt.Printf("\n\n\n")
}

#!/usr/bin/env python3
"""Shared feature-level acceptance logic for visual sculpt passes."""

from __future__ import annotations

from typing import Any


def is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def feature_review_policy(spec: dict[str, Any]) -> dict[str, Any]:
    loop = spec.get("selfCorrectLoop")
    if not isinstance(loop, dict):
        return {}
    acceptance = loop.get("visualAcceptance")
    if not isinstance(acceptance, dict):
        return {}
    policy = acceptance.get("featureReviewPolicy")
    return policy if isinstance(policy, dict) else {}


def feature_targets_for_pass(spec: dict[str, Any], pass_id: str) -> list[dict[str, Any]]:
    targets = spec.get("featureReviewTargets", [])
    if not isinstance(targets, list):
        return []
    applicable: list[dict[str, Any]] = []
    for target in targets:
        if not isinstance(target, dict):
            continue
        pass_ids = target.get("passIds", [])
        if isinstance(pass_ids, list) and pass_id in pass_ids:
            applicable.append(target)
    return applicable


def feature_gate_failures(
    spec: dict[str, Any],
    entry: dict[str, Any],
    pass_id: str,
) -> list[str]:
    policy = feature_review_policy(spec)
    if policy.get("enabled") is not True:
        return []

    targets = feature_targets_for_pass(spec, pass_id)
    critical = [
        target
        for target in targets
        if target.get("tier") == "critical" or target.get("mustPass") is True
    ]
    max_critical = policy.get("maxCriticalFeaturesPerPass", 5)
    failures: list[str] = []
    if is_number(max_critical) and len(critical) > int(max_critical):
        failures.append(
            f"pass {pass_id!r} defines {len(critical)} critical features; "
            f"group them into at most {int(max_critical)} semantic systems"
        )
    important = [target for target in targets if target.get("tier") == "important"]
    max_important = policy.get("maxImportantFeaturesPerPass", 3)
    if is_number(max_important) and len(important) > int(max_important):
        failures.append(
            f"pass {pass_id!r} defines {len(important)} important features; "
            f"keep only the {int(max_important)} most uncertain or high-value systems"
        )

    reviews = entry.get("featureReviews", [])
    review_by_id = {
        review.get("id"): review
        for review in reviews
        if isinstance(review, dict) and isinstance(review.get("id"), str)
    } if isinstance(reviews, list) else {}

    default_threshold = policy.get("criticalDefaultThreshold", 0.8)
    for target in critical:
        target_id = target.get("id")
        if not isinstance(target_id, str) or not target_id:
            continue
        review = review_by_id.get(target_id)
        if not isinstance(review, dict):
            failures.append(f"critical feature {target_id!r} has no AI vision review")
            continue
        if review.get("visible") is False:
            failures.append(f"critical feature {target_id!r} is not visible in the review view")
            continue
        score = review.get("score")
        minimum = target.get("minimumScore", default_threshold)
        if not is_number(score):
            failures.append(f"critical feature {target_id!r} has no numeric score")
        elif not is_number(minimum) or float(score) < float(minimum):
            failures.append(
                f"critical feature {target_id!r} score {score} is below {minimum}"
            )
    important_ids = {
        target.get("id")
        for target in targets
        if target.get("tier") == "important" and isinstance(target.get("id"), str)
    }
    important_scores = [
        float(review["score"])
        for feature_id, review in review_by_id.items()
        if feature_id in important_ids and is_number(review.get("score"))
    ]
    important_threshold = policy.get("importantAverageThreshold", 0.65)
    if important_scores and is_number(important_threshold):
        average = sum(important_scores) / len(important_scores)
        if average < float(important_threshold):
            failures.append(
                f"reviewed important features average {average:.3f} is below "
                f"{float(important_threshold):.3f}"
            )
    return failures

#!/usr/bin/env python3
"""Optional Playwright adapter for the Python↔Three.js render bridge.

The target page must expose:

    window.__IMG2THREEJS_READY__ = true
    window.__IMG2THREEJS_CAPTURE__.setCamera(cameraSpec)

The adapter captures the actual browser canvas/viewport. It never renders a
replacement scene in Python and fails closed when the runtime contract is absent.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from forge.stage4_review.render_bridge import (  # noqa: E402
    find_capture,
    manifest_path,
    read_manifest,
    record_capture,
    record_capture_pass,
    record_reference_capture,
    PASS_IDS,
    write_manifest,
)


def capture(manifest_path_value: Path, capture_ids: list[str], headed: bool, timeout_ms: int, mode: str) -> dict:
    try:
        from playwright.sync_api import Error as PlaywrightError  # type: ignore[import-not-found]
        from playwright.sync_api import sync_playwright  # type: ignore[import-not-found]
    except ImportError as exc:
        raise RuntimeError(
            "Playwright is not installed. Install it in an isolated environment "
            "(`python3 -m pip install playwright` and `playwright install chromium`) "
            "or use the existing Chrome DevTools MCP adapter."
        ) from exc

    manifest = read_manifest(manifest_path_value)
    runtime = manifest.get("runtime", {})
    viewport = runtime.get("viewport", [620, 1000])
    dpr = float(runtime.get("devicePixelRatio", 1))
    url = str(runtime.get("url", ""))
    if not url:
        raise ValueError("manifest runtime.url is missing")
    reference = manifest.get("reference", {})
    fidelity_v2 = manifest.get("fidelityTrack") == "glb-mediated-v2"
    if mode == "reference":
        if reference.get("kind") != "glb":
            raise ValueError("--mode reference requires a GLB reference manifest")
        if not reference.get("browserUrl"):
            raise ValueError("GLB reference manifest needs reference.browserUrl for the browser adapter")
    selected = capture_ids or [str(item["id"]) for item in manifest.get("captures", [])]
    console_errors: list[str] = []
    page_errors: list[str] = []
    browser_info: dict = {}

    try:
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch(headless=not headed)
            browser_info = {"adapter": "playwright", "browser": "chromium", "headless": not headed}
            context = browser.new_context(
                viewport={"width": int(viewport[0]), "height": int(viewport[1])},
                device_scale_factor=dpr,
            )
            page = context.new_page()
            page.on("pageerror", lambda error: page_errors.append(str(error)))
            page.on("console", lambda message: console_errors.append(message.text) if message.type == "error" else None)
            page.goto(url, wait_until="domcontentloaded", timeout=timeout_ms)
            page.wait_for_function("() => Boolean(window.__IMG2THREEJS_READY__)", timeout=timeout_ms)

            if fidelity_v2:
                pass_contract = page.evaluate(
                    "() => ({capturePass: typeof window.__IMG2THREEJS_CAPTURE__?.capturePass === 'function'})"
                )
                if not pass_contract.get("capturePass"):
                    raise RuntimeError(
                        "GLB-mediated-v2 route must expose "
                        "window.__IMG2THREEJS_CAPTURE__.capturePass({passId, mode})"
                    )

            mode_result = page.evaluate(
                """
                async ({mode, reference}) => {
                  const api = window.__IMG2THREEJS_CAPTURE__;
                  if (mode !== 'reference') return {ok: true};
                  if (!api || typeof api.setReferenceMode !== 'function') {
                    return {ok: false, reason: 'window.__IMG2THREEJS_CAPTURE__.setReferenceMode is missing'};
                  }
                  await api.setReferenceMode({kind: 'glb', url: reference.browserUrl});
                  return {ok: true};
                }
                """,
                {"mode": mode, "reference": reference},
            )
            if not mode_result.get("ok"):
                raise RuntimeError(str(mode_result.get("reason", "reference mode contract failed")))

            for capture_id in selected:
                capture_spec = find_capture(manifest, capture_id)
                result = page.evaluate(
                    """
                    async (camera) => {
                      const api = window.__IMG2THREEJS_CAPTURE__;
                      if (!api || typeof api.setCamera !== 'function') {
                        return {ok: false, reason: 'window.__IMG2THREEJS_CAPTURE__.setCamera is missing'};
                      }
                      await api.setCamera(camera);
                      return {ok: true};
                    }
                    """,
                    capture_spec,
                )
                if not result.get("ok"):
                    raise RuntimeError(str(result.get("reason", "camera contract failed")))
                page.evaluate(
                    """
                    async (frames) => {
                      for (let i = 0; i < frames; i += 1) {
                        await new Promise((resolve) => requestAnimationFrame(resolve));
                      }
                    }
                    """,
                    2,
                )
                canvas = page.evaluate(
                    """
                    () => {
                      const canvas = document.querySelector('canvas');
                      return canvas ? {width: canvas.width, height: canvas.height} : null;
                    }
                    """
                )
                if not canvas or canvas["width"] <= 0 or canvas["height"] <= 0:
                    raise RuntimeError("Three.js canvas has zero dimensions")
                if mode == "reference":
                    reference_spec = capture_spec.get("reference")
                    if not isinstance(reference_spec, dict) or not reference_spec.get("path"):
                        raise RuntimeError(f"capture {capture_id} has no GLB reference path")
                    screenshot = manifest_path(manifest_path_value, str(reference_spec["path"]))
                else:
                    screenshot = manifest_path(manifest_path_value, str(capture_spec["path"]))
                screenshot.parent.mkdir(parents=True, exist_ok=True)
                if fidelity_v2:
                    # The capture contract may return a selector when the route has a
                    # dedicated pass canvas; default to the target Three.js canvas.
                    pass_result = page.evaluate(
                        """
                        async ({passId, mode}) => {
                          const api = window.__IMG2THREEJS_CAPTURE__;
                          const result = await api.capturePass({passId, mode});
                          return result || {ok: true};
                        }
                        """,
                        {"passId": "beauty", "mode": mode},
                    )
                    if pass_result.get("ok") is False:
                        raise RuntimeError(str(pass_result.get("reason", "beauty pass failed")))
                    selector = str(pass_result.get("selector", "canvas"))
                    page.locator(selector).screenshot(path=str(screenshot))
                else:
                    page.screenshot(path=str(screenshot), full_page=False)
                ready_value = page.evaluate("() => window.__IMG2THREEJS_READY__")
                if mode == "reference":
                    record_reference_capture(
                        manifest_path_value,
                        manifest,
                        capture_id,
                        screenshot,
                        ready_signal=ready_value,
                        console_errors=console_errors + page_errors,
                    )
                else:
                    record_capture(
                        manifest_path_value,
                        manifest,
                        capture_id,
                        screenshot,
                        ready_signal=ready_value,
                        console_errors=console_errors + page_errors,
                        browser_snapshot={"canvas": canvas},
                    )

                if fidelity_v2:
                    for pass_id in PASS_IDS:
                        if pass_id == "beauty":
                            pass_path = screenshot
                        else:
                            target = capture_spec.get("reference") if mode == "reference" else capture_spec
                            pass_path = manifest_path(manifest_path_value, str(target["passes"][pass_id]["path"]))
                            pass_path.parent.mkdir(parents=True, exist_ok=True)
                            pass_result = page.evaluate(
                                """
                                async ({passId, mode}) => {
                                  const api = window.__IMG2THREEJS_CAPTURE__;
                                  const result = await api.capturePass({passId, mode});
                                  return result || {ok: true};
                                }
                                """,
                                {"passId": pass_id, "mode": mode},
                            )
                            if pass_result.get("ok") is False:
                                raise RuntimeError(str(pass_result.get("reason", "diagnostic pass failed")))
                            selector = str(pass_result.get("selector", "canvas"))
                            page.locator(selector).screenshot(path=str(pass_path))
                        record_capture_pass(
                            manifest_path_value,
                            manifest,
                            capture_id,
                            pass_id,
                            pass_path,
                            reference=mode == "reference",
                        )

            browser.close()
    except PlaywrightError as exc:
        raise RuntimeError(f"Playwright capture failed: {exc}") from exc

    manifest.setdefault("evidence", {})["browser"] = browser_info
    manifest["evidence"]["consoleErrors"] = console_errors + page_errors
    write_manifest(manifest_path_value, manifest)
    return {"captured": selected, "mode": mode, "browser": browser_info, "consoleErrors": console_errors + page_errors}


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--manifest", type=Path, required=True)
    parser.add_argument("--capture-id", action="append", default=[], help="capture only this id; repeatable")
    parser.add_argument("--headed", action="store_true")
    parser.add_argument("--timeout-ms", type=int, default=30000)
    parser.add_argument("--mode", choices=("procedural", "reference"), default="procedural")
    args = parser.parse_args(argv)
    try:
        result = capture(args.manifest.expanduser().resolve(), args.capture_id, args.headed, args.timeout_ms, args.mode)
        print(json.dumps(result, indent=2, ensure_ascii=False))
        return 0 if not result["consoleErrors"] else 1
    except Exception as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

import { describe, it, expect } from "vitest";
import { spawn } from "node:child_process";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { getTestMcpServerCommand } from "@modelcontextprotocol/inspector-test-server";

const here = dirname(fileURLToPath(import.meta.url));
const BIN = resolve(here, "../build/index.js");

/**
 * The two bounds on a spawned child, which used to be the identical 15000 —
 * so which one fired was arbitrary, and they do different things (#2323).
 *
 * `CHILD_TIMEOUT_MS` kills the child's process group and rejects with a message
 * naming the CLI. The enclosing per-test budget just fails the test generically
 * and leaves a detached `node` behind. The useful diagnostic is the child
 * timer's, so it has to be the bound that wins — and the way to arrange that is
 * to raise the test's budget above it, not to shrink the child's. Shrinking it
 * would take load tolerance away from the one suite here that spawns a real
 * process, which is the opposite of this change's purpose (Copilot).
 *
 * `E2E_SPAWN_MS` is therefore an exception to the cli project's shared 15000,
 * and one of the few sites that should be: booting the built binary in a fresh
 * `node` and waiting for it to speak to an MCP server is elapsed work, not
 * slack. It is the child's own budget plus room for the spawn and the reject to
 * be observed.
 */
const CHILD_TIMEOUT_MS = 15_000;
const E2E_SPAWN_MS = 25_000;

interface SpawnResult {
  exitCode: number | null;
  stdout: string;
  stderr: string;
}

/**
 * Spawn the **built** CLI binary as a real subprocess. This is the deliberately
 * thin out-of-process layer that the in-process suite (cli-runner.ts) cannot
 * reach: the shebang, `index.ts`'s `isMain` bootstrap, and the actual
 * `process.exit` codes. Functional behavior is covered in-process under the
 * coverage gate; this only asserts the binary boots and exits correctly. The
 * binary is built by the `pretest` / `test:coverage` scripts before tests run.
 */
function spawnCli(args: string[]): Promise<SpawnResult> {
  return new Promise((resolvePromise, reject) => {
    const child = spawn("node", [BIN, ...args], {
      stdio: ["pipe", "pipe", "pipe"],
      detached: process.platform !== "win32",
    });
    let stdout = "";
    let stderr = "";
    const timer = setTimeout(() => {
      if (process.platform !== "win32" && child.pid != null) {
        process.kill(-child.pid, "SIGTERM");
      } else {
        child.kill("SIGTERM");
      }
      reject(new Error("E2E CLI timed out"));
    }, CHILD_TIMEOUT_MS);
    child.stdout.on("data", (d) => (stdout += d.toString()));
    child.stderr.on("data", (d) => (stderr += d.toString()));
    child.on("error", (err) => {
      clearTimeout(timer);
      reject(err);
    });
    child.on("close", (exitCode) => {
      clearTimeout(timer);
      resolvePromise({ exitCode, stdout, stderr });
    });
  });
}

describe("CLI binary (out-of-process E2E)", () => {
  const { command, args } = getTestMcpServerCommand();

  it(
    "exits 0 and prints tools JSON on a successful run",
    async () => {
      const result = await spawnCli([
        command,
        ...args,
        "--method",
        "tools/list",
      ]);

      expect(result.exitCode).toBe(0);
      const json = JSON.parse(result.stdout);
      expect(Array.isArray(json.tools)).toBe(true);
    },
    E2E_SPAWN_MS,
  );

  it(
    "exits non-zero when required --method is missing",
    async () => {
      const result = await spawnCli([command, ...args]);

      expect(result.exitCode).not.toBe(0);
      expect(result.stderr).toContain("Method is required");
    },
    E2E_SPAWN_MS,
  );
});

import { describe, it, expect, vi } from "vitest";
import type { InspectorClientProtocol } from "@inspector/core/mcp/inspectorClientProtocol.js";
import {
  DYNAMIC_RESOURCES,
  type SkillEntry,
} from "@inspector/core/mcp/skillsSchemas.js";
import {
  SKILL_MAX_CATALOG_SKILLS,
  sha256Digest,
} from "@inspector/core/mcp/skills.js";
import { AuthRecoveryRequiredError } from "@inspector/core/auth/challenge.js";
import {
  allSkillsVerified,
  anySkillFailed,
  utf8Length,
  verifySkills,
} from "@inspector/core/mcp/skillsVerification.js";

/**
 * `verifySkills` is the fetch-and-verify half of the SEP-2640 checks (#2248) —
 * the part the pure checkers in `skills.ts` deliberately do not do. What these
 * pin is the fetching policy and the failure handling, since the checks
 * themselves are covered in `skills.test.ts`.
 */

/**
 * A manifest big enough to be truncated, whose files all VERIFY — so the
 * report's outcome isolates "incomplete" instead of also tripping a real
 * failure. The entry's own SKILL.md carries frontmatter matching the listing,
 * since a body of "x" would be `frontmatter-absent` and so genuinely failed.
 */
async function truncatable(options: {
  name: string;
  count: number;
  body?: string;
}): Promise<{ skill: SkillEntry; client: InspectorClientProtocol }> {
  const { name, count, body = "x" } = options;
  const md = `---\nname: ${name}\ndescription: Big\n---\n\n# ${name}\n`;
  const enc = new TextEncoder();
  const selfDigest = await sha256Digest(enc.encode(md));
  const bodyDigest = await sha256Digest(enc.encode(body));
  const selfUri = `skill://${name}/SKILL.md`;
  const skill: SkillEntry = {
    uri: selfUri,
    frontmatter: { name, description: "Big" },
    resources: Array.from({ length: count }, (_, i) =>
      i === 0
        ? { uri: selfUri, digest: selfDigest, size: enc.encode(md).byteLength }
        : {
            uri: `skill://${name}/f${i}.md`,
            digest: bodyDigest,
            size: enc.encode(body).byteLength,
          },
    ),
  };
  const client = {
    readResource: async (uri: string) => ({
      result: { contents: [{ uri, text: uri === selfUri ? md : body }] },
    }),
  } as unknown as InspectorClientProtocol;
  return { skill, client };
}

describe("verifySkills (#2248)", () => {
  const SKILL_MD = "---\nname: demo\ndescription: A demo\n---\n\n# Demo\n";
  const REF = "# Reference\n";

  async function entry(
    overrides: Partial<SkillEntry> = {},
  ): Promise<SkillEntry> {
    return {
      uri: "skill://demo/SKILL.md",
      frontmatter: { name: "demo", description: "A demo" },
      resources: [
        {
          uri: "skill://demo/SKILL.md",
          digest: await sha256Digest(new TextEncoder().encode(SKILL_MD)),
          size: new TextEncoder().encode(SKILL_MD).byteLength,
        },
        {
          uri: "skill://demo/ref.md",
          digest: await sha256Digest(new TextEncoder().encode(REF)),
          size: new TextEncoder().encode(REF).byteLength,
        },
      ],
      ...overrides,
    };
  }

  /** A client whose `resources/read` answers from a URI → text map. */
  function clientServing(files: Record<string, string | Error>): {
    client: InspectorClientProtocol;
    readResource: ReturnType<typeof vi.fn>;
  } {
    const readResource = vi.fn(async (uri: string) => {
      const served = files[uri];
      if (served === undefined) throw new Error(`unknown resource ${uri}`);
      if (served instanceof Error) throw served;
      return { result: { contents: [{ uri, text: served }] } };
    });
    return {
      client: { readResource } as unknown as InspectorClientProtocol,
      readResource,
    };
  }

  it("verifies a clean skill and reports ok", async () => {
    const skill = await entry();
    const { client } = clientServing({
      "skill://demo/SKILL.md": SKILL_MD,
      "skill://demo/ref.md": REF,
    });
    const [report] = await verifySkills(client, [skill]);
    expect(report.ok).toBe(true);
    expect(report.name).toBe("demo");
    expect(report.conformance).toEqual([]);
    expect(report.frontmatter).toEqual([]);
    expect(report.files.map((f) => f.status)).toEqual(["verified", "verified"]);
    expect(allSkillsVerified([report])).toBe(true);
  });

  it("reads each manifest file exactly once", async () => {
    // The entry's own SKILL.md is needed twice — for its digest and for the
    // frontmatter cross-check — and reading it twice would both double the
    // load and risk comparing two different snapshots.
    const skill = await entry();
    const { client, readResource } = clientServing({
      "skill://demo/SKILL.md": SKILL_MD,
      "skill://demo/ref.md": REF,
    });
    await verifySkills(client, [skill]);
    expect(readResource).toHaveBeenCalledTimes(2);
  });

  it("reports a digest mismatch and fails the skill", async () => {
    const skill = await entry();
    const { client } = clientServing({
      "skill://demo/SKILL.md": SKILL_MD,
      "skill://demo/ref.md": "different bytes entirely\n",
    });
    const [report] = await verifySkills(client, [skill]);
    expect(report.ok).toBe(false);
    expect(report.files[1].status).toBe("mismatch");
    expect(allSkillsVerified([report])).toBe(false);
  });

  it("catches a listing whose frontmatter differs from the served file", async () => {
    const skillMd = "---\nname: demo\ndescription: Something else\n---\n\n#\n";
    const bytes = new TextEncoder().encode(skillMd);
    const skill: SkillEntry = {
      uri: "skill://demo/SKILL.md",
      frontmatter: { name: "demo", description: "A demo" },
      resources: [
        {
          uri: "skill://demo/SKILL.md",
          // The digest is over the bytes actually served, so it VERIFIES —
          // which is the whole reason this check has to exist separately.
          digest: await sha256Digest(bytes),
          size: bytes.byteLength,
        },
      ],
    };
    const { client } = clientServing({ "skill://demo/SKILL.md": skillMd });
    const [report] = await verifySkills(client, [skill]);
    expect(report.files[0].status).toBe("verified");
    expect(report.frontmatter).toHaveLength(1);
    expect(report.ok).toBe(false);
  });

  it("records a read failure per file instead of aborting the report", async () => {
    // A report that stopped at the first unreadable file would hide every
    // finding after it, which defeats the point of running this in CI.
    const skill = await entry();
    const { client } = clientServing({
      "skill://demo/SKILL.md": new Error("boom"),
      "skill://demo/ref.md": REF,
    });
    const [report] = await verifySkills(client, [skill]);
    expect(report.files[0]).toMatchObject({
      status: "read-error",
      reason: "boom",
    });
    expect(report.files[1].status).toBe("verified");
    expect(report.ok).toBe(false);
  });

  it("refuses a block for a DIFFERENT uri rather than verifying it", async () => {
    // The dangerous shape, and the reason positional selection is wrong: these
    // bytes are about to be hashed against THIS file's advertised digest, so
    // accepting a block the server labelled something else verifies one file's
    // content against another file's digest — and can report that as
    // `verified`. A false pass is worse than a missing check.
    const skill = await entry();
    const readResource = vi.fn(async () => ({
      result: {
        contents: [{ uri: "skill://demo/unrelated.md", text: "other bytes" }],
      },
    }));
    const client = { readResource } as unknown as InspectorClientProtocol;
    const [report] = await verifySkills(client, [skill]);
    expect(report.files.every((f) => f.status === "read-error")).toBe(true);
    expect(report.files[0].reason).toMatch(/no content block for this URI/);
    expect(report.ok).toBe(false);
  });

  it("finds the matching block when it is not the first one", async () => {
    // A server may answer with more than one block, in any order; taking
    // `contents[0]` would hash the wrong file's bytes.
    const bytes = new TextEncoder().encode(REF);
    const skill: SkillEntry = {
      uri: "skill://demo/SKILL.md",
      frontmatter: { name: "demo", description: "A demo" },
      resources: [
        {
          uri: "skill://demo/ref.md",
          digest: await sha256Digest(bytes),
          size: bytes.byteLength,
        },
      ],
    };
    const readResource = vi.fn(async () => ({
      result: {
        contents: [
          { uri: "skill://demo/decoy.md", text: "decoy" },
          { uri: "skill://demo/ref.md", text: REF },
        ],
      },
    }));
    const client = { readResource } as unknown as InspectorClientProtocol;
    const [report] = await verifySkills(client, [skill]);
    expect(report.files[0].status).toBe("verified");
  });

  it("ignores a malformed block while still finding the real one", async () => {
    const bytes = new TextEncoder().encode(REF);
    const skill: SkillEntry = {
      uri: "skill://demo/SKILL.md",
      frontmatter: { name: "demo", description: "A demo" },
      resources: [
        {
          uri: "skill://demo/ref.md",
          digest: await sha256Digest(bytes),
          size: bytes.byteLength,
        },
      ],
    };
    const readResource = vi.fn(async () => ({
      result: {
        contents: [
          null,
          { uri: 42 },
